module iso7816_d4_padding
@[export: 'iso7816_d4_padding']
pub fn iso7816_d4_padding(v &i64,n usize)i64{if n<3||n>27{return -1};mode:=unsafe{v[0]};block:=unsafe{v[1]};length:=unsafe{v[2]};if mode<0||mode>2||(mode==0&&(block<1||block>8))||(mode!=0&&block!=0)||length<0||length>24||n!=usize(length+3){return -1};mut data:=[32]i64{};for i in 0..int(length){data[i]=unsafe{v[i+3]};if data[i]<0||data[i]>255{return -1}};if mode==0{out:=(length/block+1)*block;if out>32{return -1};data[length]=128;for i in int(length+1)..int(out){data[i]=0};return out-length};if mode==1{mut i:=int(length)-1;for i>=0&&data[i]==0{i--};if i>=0&&data[i]==128{return i};return -1};mut marker:=-1;mut zero_suffix:=true;mut j:=int(length)-1;for j>=0{if zero_suffix&&data[j]==128{marker=j};if data[j]!=0{zero_suffix=false};j--};if marker>=0{return length-marker};return -1}
